AOD_ABILITIES_PLAYER_CACHE={}AOD_ABILITIES={{["name"]="aod_anti_inf_gas",["cost"]=300},{["name"]="aod_atomic_bomb",["cost"]=400},{["name"]="aod_bombing",["cost"]=500},{["name"]="aod_extra_unit_pass",["cost"]=1000,["gametype_not"]="annihilation"},{["name"]="aod_freeze_units",["cost"]=100},{["name"]="aod_heal_units",["cost"]=250},{["name"]="aod_reinforce_infantry",["cost"]=800},{["name"]="aod_sector_artillery",["cost"]=600},{["name"]="aod_tiger_tank",["cost"]=800},{["name"]="aod_vehicles_ooc",["cost"]=400},}
function AOD_Ability_SpendCost(player,abilityName)local ability=AOD_Ability_Find(abilityName)if(ability~=nil)then AOD_Points_SpendPlayerScore(player,ability["cost"])end end function AOD_Ability_Find(name)for i,ability in pairs(AOD_ABILITIES)do if(ability["name"]==name)then return ability end end return nil end function AOD_Ability_AddPlayerAbility(player)if(POINTS_DISPLAY==nil)then return end for i,ability in ipairs(AOD_ABILITIES)do if(ability["blueprint"]==nil)then AOD_ABILITIES[i]["blueprint"]=BP_GetAbilityBlueprint(MODID..":"..ability["name"])end local doAdd=false if(ability["gametype"]==nil and ability["gametype_not"]==nil)then doAdd=true else if(ability["gametype"]~=nil and ability["gametype"]==lose_condition)then doAdd=true elseif(ability["gametype_not"]~=nil and ability["gametype_not"]~=lose_condition)then doAdd=true end end if(doAdd)then local abilityBlueprint=AOD_ABILITIES[i]["blueprint"]Player_AddAbility(player,abilityBlueprint)Player_SetAbilityAvailability(player,abilityBlueprint,ITEM_LOCKED)local playerID=Player_GetID(player)if(AOD_ABILITIES_PLAYER_CACHE[playerID]==nil)then AOD_ABILITIES_PLAYER_CACHE[playerID]={}end AOD_ABILITIES_PLAYER_CACHE[playerID][ability["name"]]=false end end end function AOD_Ability_UpdatePlayerAbilities()Profiler_StartFunction("AOD_Ability_UpdatePlayerAbilities")if(POINTS_DISPLAY==nil)then return end humanPlayers=Team_GetPlayers(0)for i,player in ipairs(humanPlayers)do playerScore=AOD_Points_GetPlayerAvailableScore(player)for j,ability in ipairs(AOD_ABILITIES)do local abilityBlueprint=ability["blueprint"]local scoreNeeded=ability["cost"]local playerID=Player_GetID(player)if(AOD_ABILITIES_PLAYER_CACHE[playerID][ability["name"]]==false and playerScore>=scoreNeeded)then Player_SetAbilityAvailability(player,abilityBlueprint,ITEM_DEFAULT)AOD_ABILITIES_PLAYER_CACHE[playerID][ability["name"]]=true elseif(AOD_ABILITIES_PLAYER_CACHE[playerID][ability["name"]]==true and playerScore<scoreNeeded)then Player_SetAbilityAvailability(player,abilityBlueprint,ITEM_LOCKED)AOD_ABILITIES_PLAYER_CACHE[playerID][ability["name"]]=false end end end Profiler_EndFunction("AOD_Ability_UpdatePlayerAbilities")end
ABILITIES_ANTI_INF_UNITS={}function AOD_Ability_AntiInfGas(executer,target)local caster=Util_GetPlayerOwner(executer)local abilityPos=Util_GetPosition(target)table.insert(ABILITIES_ANTI_INF_UNITS,{["position"]=abilityPos,["start"]=World_GetGameTime(),["duration"]=15,["damage"]=0.1})if(not Rule_Exists(AOD_Ability_DamageInfantry))then Rule_AddInterval(AOD_Ability_DamageInfantry,1,900)end AOD_Ability_SpendCost(caster,"aod_anti_inf_gas")end function AOD_Ability_DamageInfantry()for i,group in pairs(ABILITIES_ANTI_INF_UNITS)do local squadGroup=SGroup_CreateIfNotFound("aod_ability_antiinf")local damage=group["damage"]Player_GetAllSquadsNearMarker(AIPlayer1,squadGroup,group["position"],20)local function RemoveVehicles(groupid,itemindex,itemid)local squadEntity=Squad_EntityAt(itemid,0)if(Entity_IsVehicle(squadEntity)and not Squad_HasTeamWeapon(itemid))then SGroup_Remove(squadGroup,itemid)end end SGroup_ForEach(squadGroup,RemoveVehicles)local function DoDamage(groupid,itemindex,itemid)local newHealth=Squad_GetHealthPercentage(itemid)-damage if(newHealth<0)then newHealth=0 elseif(newHealth>1)then newHealth=1 end if(newHealth>=0.05)then Squad_SetHealth(itemid,newHealth)else Squad_Kill(itemid)end end SGroup_ForEach(squadGroup,DoDamage)SGroup_Destroy(squadGroup)if(World_GetGameTime()-group["start"]>=group["duration"])then table.remove(ABILITIES_ANTI_INF_UNITS,i)end end if(#ABILITIES_ANTI_INF_UNITS==0)then Rule_RemoveMe()end end
function AOD_Ability_AtomicBomb(executer,target)local caster=Util_GetPlayerOwner(executer)AOD_Ability_SpendCost(caster,"aod_atomic_bomb")end
function AOD_Ability_Bombing(executer,target)local caster=Util_GetPlayerOwner(executer)AOD_Ability_SpendCost(caster,"aod_bombing")end
function AOD_Ability_ExtraUnitPass(executer,target)local caster=Util_GetPlayerOwner(executer)UNITS_PASSED_COUNTER=UNITS_PASSED_COUNTER-1 Util_ShowMissionTitle(Loc_FormatText(Util_CreateLocId(1337022),Player_GetDisplayName(caster)),1.0,8.0,1.0)
AOD_Ability_SpendCost(caster,"aod_extra_unit_pass")end
ABILITIES_FROZEN_UNITS={}function AOD_Ability_FreezeUnits(executer,target)local caster=Util_GetPlayerOwner(executer)local abilityPos=Util_GetPosition(target)local squadGroup=SGroup_CreateIfNotFound("aod_ability_frezuni"..World_GetGameTime())
Player_GetAllSquadsNearMarker(AIPlayer1,squadGroup,abilityPos,20)Cmd_Stop(squadGroup)Modify_WeaponEnabled(squadGroup,"hardpoint_01",false)Modify_WeaponEnabled(squadGroup,"hardpoint_02",false)Modify_WeaponEnabled(squadGroup,"hardpoint_03",false)Modify_WeaponEnabled(squadGroup,"hardpoint_04",false)Modify_WeaponEnabled(squadGroup,"hardpoint_05",false)table.insert(ABILITIES_FROZEN_UNITS,{["group"]=squadGroup,["start"]=World_GetGameTime(),["duration"]=15})if(not Rule_Exists(AOD_Ability_UnfreezeUnits))then Rule_AddInterval(AOD_Ability_UnfreezeUnits,0.2,900)end AOD_Ability_SpendCost(caster,"aod_freeze_units")end function AOD_Ability_UnfreezeUnits()for i,group in pairs(ABILITIES_FROZEN_UNITS)do if(World_GetGameTime()-group["start"]>=group["duration"])then Modify_WeaponEnabled(group["group"],"hardpoint_01",true)Modify_WeaponEnabled(group["group"],"hardpoint_02",true)Modify_WeaponEnabled(group["group"],"hardpoint_03",true)Modify_WeaponEnabled(group["group"],"hardpoint_04",true)Modify_WeaponEnabled(group["group"],"hardpoint_05",true)SGroup_Destroy(group["group"])table.remove(ABILITIES_FROZEN_UNITS,i)end end if(#ABILITIES_FROZEN_UNITS==0)then Rule_RemoveMe()end end function AOD_Ability_GetFrozenUnits()local totalGroup=SGroup_CreateIfNotFound("aod_ability_fezuni_total")for i,group in pairs(ABILITIES_FROZEN_UNITS)do SGroup_AddGroup(totalGroup,group["group"])end return totalGroup end
function AOD_Ability_HealUnits(executer,target)local caster=Util_GetPlayerOwner(executer)AOD_Ability_SpendCost(caster,"aod_heal_units")end
function AOD_Ability_ReinforceInfantry(executer,target)local caster=Util_GetPlayerOwner(executer)local friendlyInfantry=SGroup_CreateIfNotFound("aod_ability_reinfinf")local tempSquadGroup=SGroup_CreateIfNotFound("aod_ability_reinfinf_tmp")for index,humanPlayer in pairs(HUMAN_PLAYERS)do SGroup_AddGroup(friendlyInfantry,Player_GetSquads(humanPlayer))end local function RemoveVehicles(groupid,itemindex,itemid)local squadEntity=Squad_EntityAt(itemid,0)if(Entity_IsVehicle(squadEntity)and not Squad_HasTeamWeapon(itemid))then SGroup_Remove(friendlyInfantry,itemid)end end SGroup_ForEach(friendlyInfantry,RemoveVehicles)local function RecrewSquad(groupid,itemindex,itemid)local count=Squad_Count(itemid)local maxCount=Squad_GetMax(itemid)SGroup_Clear(tempSquadGroup)SGroup_Add(tempSquadGroup,itemid)Cmd_InstantReinforceUnitPos(tempSquadGroup,maxCount-count,Squad_GetPosition(itemid),CHECK_OFFCAMERA,SPAWN_ATSQUAD)end SGroup_ForEach(friendlyInfantry,RecrewSquad)SGroup_Destroy(tempSquadGroup)SGroup_Destroy(friendlyInfantry)Util_ShowMissionTitle(Loc_FormatText(Util_CreateLocId(1337023),Player_GetDisplayName(caster)),1.0,8.0,1.0)
AOD_Ability_SpendCost(caster,"aod_reinforce_infantry")end
